mapper.select:
-- 다른 source의 판정은 반환하지 않는다.
SELECT  FROM announcement_source_attachment_evaluations e
WHERE e.id=#{evaluationId} AND e.source_id=#{sourceId}

-- 같은 입력과 엔진의 재저장은 불변 판정을 재사용한다.
SELECT  FROM announcement_source_attachment_evaluations e
WHERE e.source_id=#{sourceId} AND e.input_hash=#{inputHash} AND e.engine_version=#{engineVersion}
